result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/toposort.ts", "content": "/**
 * Topological sort (Kahn's algorithm) with cycle diagnostics.
 *
 * On success returns `{ order }` — a topological ordering of all nodes.
 * If the graph contains a cycle, returns `{ cycle }` — one actual cycle
 * as a node path `[a, b, ..., a]`, discovered via DFS on the subgraph
 * left over after Kahn's algorithm stalls.
 */

export type ToposortResult =
  | { order: string[] }
  | { cycle: [first: string, ...rest: string[]] };

export function toposort(edges: readonly (readonly [string, string])[]): ToposortResult {
  // --- Build adjacency list, in-degree counts, and node set -------------
  const adjacency = new Map<string, Set<string>>();
  const inDegree = new Map<string, number>();
  const nodes = new Set<string>();

  for (const [from, to] of edges) {
    nodes.add(from);
    nodes.add(to);
    if (!adjacency.has(from)) adjacency.set(from, new Set());
    if (!adjacency.has(to)) adjacency.set(to, new Set());
    // Ignore duplicate edges so in-degree stays consistent.
    if (!adjacency.get(from)!.has(to)) {
      adjacency.get(from)!.add(to);
      inDegree.set(to, (inDegree.get(to) ?? 0) + 1);
    }
  }
  for (const node of nodes) {
    if (!inDegree.has(node)) inDegree.set(node, 0);
  }

  // --- Kahn's algorithm --------------------------------------------------
  const queue: string[] = [...inDegree.entries()]
    .filter(([, deg]) => deg === 0)
    .map(([node]) => node);

  const order: string[] = [];
  while (queue.length > 0) {
    const node = queue.pop()!; // order between valid options doesn't matter
    order.push(node);
    for (const next of adjacency.get(node)!) {
      const deg = inDegree.get(next)! - 1;
      inDegree.set(next, deg);
      if (deg === 0) queue.push(next);
    }
  }

  if (order.length === nodes.size) {
    return { order };
  }

  // --- Cycle found: DFS on the leftover subgraph -------------------------
  // Leftover nodes are those Kahn's could never process (they sit on or
  // downstream of a cycle). Every remaining node has in-degree >= 1 and
  // every outgoing edge from leftover nodes leads to another leftover
  // node, so following any path must eventually revisit a node.
  const leftover = new Set<string>();
  for (const [node, deg] of inDegree) {
    if (deg > 0) leftover.add(node);
  }

  const state = new Map<string, "visiting" | "done">();
  const path: string[] = [];

  const visit = (node: string): [string, ...string[]] | null => {
    state.set(node, "visiting");
    path.push(node);
    for (const next of adjacency.get(node)!) {
      if (!leftover.has(next)) continue;
      if (state.get(next) === "visiting") {
        // Found a back-edge: slice out the cycle, close the loop.
        const start = path.indexOf(next);
        return [...path.slice(start), next] as [string, ...string[]];
      }
      if (state.get(next) === undefined) {
        const cycle = visit(next);
        if (cycle) return cycle;
      }
    }
    path.pop();
    state.set(node, "done");
    return null;
  };

  for (const node of leftover) {
    const cycle = visit(node);
    if (cycle) return { cycle };
  }

  // Unreachable for well-formed input; kept for exhaustive typing.
  throw new Error("Internal error: cycle detected but DFS found none");
}
"})
