result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tests/toposort.test.ts", "content": "import { describe, expect, it } from "vitest";
import { toposort } from "../src/toposort.js";

/** Every edge [a, b] must appear as a before b in the produced order. */
function respectsAllEdges(order: string[], edges: readonly (readonly [string, string])[]) {
  const position = new Map(order.map((node, i) => [node, i]));
  // No duplicates, no unknown nodes.
  expect(new Set(order).size).toBe(order.length);
  for (const [from, to] of edges) {
    expect(position.get(from)).toBeDefined();
    expect(position.get(to)).toBeDefined();
    expect(position.get(from)!).toBeLessThan(position.get(to)!);
  }
  // All nodes present exactly once.
  const expected = new Set(edges.flat());
  expect(new Set(order)).toEqual(expected);
}

function isActualCycle(cycle: readonly string[], edges: readonly (readonly [string, string])[]) {
  expect(cycle.length).toBeGreaterThanOrEqual(2);
  expect(cycle[0]).toBe(cycle[cycle.length - 1]); // closed loop
  const edgeSet = new Set(edges.map(([a, b]) => `${a}\u0000${b}`));
  for (let i = 0; i < cycle.length - 1; i++) {
    expect(edgeSet.has(`${cycle[i]}\u0000${cycle[i + 1]}`)).toBe(true);
  }
}

describe("toposort", () => {
  it("returns a valid ordering for a generic DAG", () => {
    const edges: [string, string][] = [
      ["b", "c"],
      ["a", "b"],
      ["c", "d"],
      ["a", "d"],
      ["d", "e"],
    ];
    const result = toposort(edges);
    expect(result).toHaveProperty("order");
    if ("order" in result) respectsAllEdges(result.order, edges);
  });

  it("handles the diamond dependency a -> b,c -> d", () => {
    const edges: [string, string][] = [
      ["a", "b"],
      ["a", "c"],
      ["b", "d"],
      ["c", "d"],
    ];
    const result = toposort(edges);
    expect(result).toHaveProperty("order");
    if ("order" in result) respectsAllEdges(result.order, edges);
  });

  it("reports an actual cycle for a 3-node cycle", () => {
    const edges: [string, string][] = [
      ["a", "b"],
      ["b", "c"],
      ["c", "a"],
      ["a", "z"], // extra edge that is not part of the cycle
    ];
    const result = toposort(edges);
    expect(result).toHaveProperty("cycle");
    if ("cycle" in result) {
      isActualCycle(result.cycle, edges);
      // The reported cycle must involve only {a, b, c}, not z.
      expect(new Set(result.cycle.slice(0, -1))).toEqual(new Set(["a", "b", "c"]));
    }
  });

  it("handles disconnected components", () => {
    const edges: [string, string][] = [
      ["a", "b"], // component 1
      ["x", "y"], // component 2
      ["p", "q"], // component 3
      ["p", "r"],
    ];
    const result = toposort(edges);
    expect(result).toHaveProperty("order");
    if ("order" in result) respectsAllEdges(result.order, edges);
  });

  it("returns an empty order for an empty edge list", () => {
    const result = toposort([]);
    expect(result).toEqual({ order: [] });
  });
});
"})
